import {calibrationMetrics} from './calibration-metrics.js';
export const eye={ready:false,active:false,last:null,samples:[],calibration:null,mode:'demo',lastSave:0,viewport:null};
let loadPromise;
function script(){return loadPromise??=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='./vendor/webgazer.js';s.onload=resolve;s.onerror=()=>{loadPromise=null;reject(Error('眼动库加载失败，请检查本地文件或网络。'));};document.head.append(s);});}
export async function startEye(){await script();const w=window.webgazer;w.params.faceMeshSolutionPath=new URL('./vendor/mediapipe/face_mesh',location.href).href;w.params.saveDataAcrossSessions=false;w.setGazeListener((data)=>{eye.last=data?{x:data.x,y:data.y,t:performance.now()}:null;if(eye.active&&data&&performance.now()-eye.lastSave>65){eye.samples.push({t:Math.round(performance.now()),x:+(data.x/innerWidth).toFixed(4),y:+(data.y/innerHeight).toFixed(4)});eye.lastSave=performance.now();}});await w.begin();w.removeMouseEventListeners();await w.clearData();w.showPredictionPoints(false);eye.ready=false;eye.mode='camera';}
export function stopEye(){window.webgazer?.end();eye.ready=false;eye.mode='demo';eye.active=false;eye.last=null;document.getElementById('webgazerVideoContainer')?.remove();}
export async function calibrate(){const layer=document.getElementById('calibration'),point=document.getElementById('cal-point'),note=document.getElementById('cal-note'),cancel=document.getElementById('cal-cancel');const points=[[.12,.15],[.5,.15],[.88,.15],[.12,.5],[.5,.5],[.88,.5],[.12,.85],[.5,.85],[.88,.85]];eye.ready=false;layer.hidden=false;window.webgazer.showVideoPreview(true);let cancelled=false;const waits=new Set();const sleep=ms=>new Promise(resolve=>{const id=setTimeout(()=>{waits.delete(id);resolve();},ms);waits.add(id);});return new Promise((resolve,reject)=>{const finish=(ok,error)=>{point.onclick=null;cancel.onclick=null;layer.hidden=true;waits.forEach(clearTimeout);if(ok){eye.ready=true;eye.viewport={w:innerWidth,h:innerHeight};window.webgazer.showVideoPreview(false);resolve(eye.calibration);}else reject(Error(error||'已退出校准。'));};cancel.onclick=()=>{cancelled=true;finish(false);};let i=0,clicks=0;function place(){const p=points[i];point.style.left=p[0]*100+'%';point.style.top=p[1]*100+'%';point.textContent=String(5-clicks);note.innerHTML=`注视绿色圆点，点击 5 次<br><small>校准 ${i+1} / 9 · 请保持头部稳定</small>`;};place();point.onclick=()=>{const rect=point.getBoundingClientRect();window.webgazer.recordScreenPosition(rect.x+rect.width/2,rect.y+rect.height/2,'click');clicks++;if(clicks<5){place();return;}clicks=0;i++;if(i<points.length){place();return;}point.onclick=null;validate();};async function validate(){const targets=[[.25,.25],[.75,.25],[.5,.65],[.25,.75],[.75,.75]],errors=[],counts=[];for(let j=0;j<targets.length;j++){if(cancelled)return;const [x,y]=targets[j];point.style.left=x*100+'%';point.style.top=y*100+'%';point.textContent='✦';note.innerHTML=`独立验证 ${j+1} / 5<br><small>只看圆点，不要点击。验证点不参与训练。</small>`;await sleep(700);let es=[];for(let k=0;k<12;k++){await sleep(80);if(cancelled)return;const p=eye.last;if(p&&performance.now()-p.t<200)es.push(Math.hypot(p.x-x*innerWidth,p.y-y*innerHeight));}counts.push(es.length);if(es.length)errors.push(es.reduce((s,e)=>s+e,0)/es.length);}if(cancelled)return;eye.calibration=calibrationMetrics(errors,counts,innerWidth,innerHeight);finish(eye.calibration.pass,'未获得眼动样本，请检查摄像头与人脸检测后重试；误差大小不作限制。');}});}
window.addEventListener('resize',()=>{if(eye.ready&&eye.viewport&&(Math.abs(innerWidth-eye.viewport.w)>20||Math.abs(innerHeight-eye.viewport.h)>20)){eye.ready=false;window.dispatchEvent(new CustomEvent('eyeinvalid'));}});
